<?php include "auth.php";include "conection.php";$id=(int)($_GET['id']??0);$q=$conn->prepare("SELECT * FROM id_aspirasi WHERE id_aspirasi=?");$q->bind_param("i",$id);$q->execute();$data=$q->get_result()->fetch_assoc();if(!$data)die("Data aspirasi tidak ditemukan.");$siswa=$conn->query("SELECT id_siswa,nama_siswa,nisn,kelas FROM siswa ORDER BY nama_siswa");$kat=$conn->query("SELECT nama_kategori FROM kategori ORDER BY nama_kategori");?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Aspirasi</title><link rel="stylesheet" href="./data.css?v=spiderman2026"></head><body><div class="app"><?php include "header.php";?><div class="form-card"><p class="eyebrow">DATA ASPIRASI</p><h1>Edit Aspirasi</h1><form action="update.php" method="post"><input type="hidden" name="id_aspirasi" value="<?=$id?>"><div class="form-group"><label>Nama Siswa</label><select name="id_siswa" required><?php while($r=$siswa->fetch_assoc()):?><option value="<?=$r['id_siswa']?>" <?=$r['id_siswa']==$data['id_siswa']?'selected':''?>><?=htmlspecialchars($r['nama_siswa'])?> — <?=htmlspecialchars($r['nisn'])?> (<?=htmlspecialchars($r['kelas'])?>)</option><?php endwhile;?></select></div><div class="form-group"><label>Kategori</label><select name="kategori" required><?php while($r=$kat->fetch_assoc()):?><option value="<?=htmlspecialchars($r['nama_kategori'])?>" <?=$r['nama_kategori']===$data['kategori']?'selected':''?>><?=htmlspecialchars($r['nama_kategori'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Isi Aspirasi</label><textarea name="isi_aspirasi" required><?=htmlspecialchars($data['isi_aspirasi'])?></textarea></div><div class="actions"><a class="btn btn-secondary" href="tampil.php">Kembali</a><button class="btn btn-primary">Simpan Perubahan</button></div></form></div><?php include "footer.php";?></div></body></html>